#pragma intrinsic(_ReadWriteBarrier)
extern "C" void _ReadWriteBarrier(void);

inline Rva002EE330Player *nextPlayerFromMask(
	Rva002EE330PlayerList *players, unsigned short *mask)
{
	return players->nextFromMask(mask);
}

inline void revealMapForPlayer(
	int index, Rva002EEDA0ShroudManager *shroud)
{
	shroud->revealMapForPlayer(index);
}

void __stdcall scriptPlayers002EEDA0RevealMap(int param)
{
	param = TheScriptEngine->resolvePlayerMask(param, 0);
	if (!(unsigned short)param)
	{
		for (int i = 0; i < Rva002EE330ThePlayers->m_count; ++i)
		{
			Rva002EE330Player *player = Rva002EF110GetPlayer(i);
			if (!player->m_isLocalOnly)
			{
				revealMapForPlayer(i, Rva002EEDA0TheShroudManager);
			}
		}
		return;
	}

	while ((unsigned short)param)
	{
		unsigned short *mask = (unsigned short *)&param;
		_ReadWriteBarrier();
		Rva002EE330Player *player =
			nextPlayerFromMask(Rva002EE330ThePlayers, mask);
		if (player)
		{
			int index = player->m_index;
			_ReadWriteBarrier();
			Rva002EEDA0ShroudManager *shroud =
				Rva002EEDA0TheShroudManager;
			shroud->revealMapForPlayer(index);
		}
	}
}
